using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any public type.
var webOptions = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1) GetTypeInfo<T>() — returns JsonTypeInfo<T> directly (no cast needed).
JsonTypeInfo<Person> personInfo = webOptions.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) TryGetTypeInfo<T>() — probes without throwing.
//    Against the reflection resolver every public type succeeds:
if (webOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");

// Now use a *source-gen* context that only knows about Person.
// Asking for int will fail — but TryGetTypeInfo won't throw.
var sgOptions = new JsonSerializerOptions { TypeInfoResolver = SmallContext.Default };

if (sgOptions.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
    Console.WriteLine($"TryGetTypeInfo<int> succeeded → {intInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<int> returned false — no metadata for int");

// Record used by the demo
public record Person(string Name, int Age);

// Source-gen context that only declares Person
[JsonSerializable(typeof(Person))]
internal partial class SmallContext : JsonSerializerContext;

